/**
 * Carga el lote de muestras industriales de calibración al Banco IA si está vacío o si se fuerza.
 * @param {boolean} forceReload
 * @returns {Promise<number>} Cantidad de muestras insertadas
 */
export async function loadFactorySeedSamplesToDB(forceReload = false) {
    try {
        const { initDatasetDB, getAllSamples } = await import('./datasetManager.js');
        const db = await initDatasetDB();
        if (!db) return 0;

        const current = await getAllSamples();
        if (current.length > 0 && !forceReload) {
            return 0; // Ya tiene muestras, no sobreescribir
        }

        const tx = db.transaction('samples', 'readwrite');
        const store = tx.objectStore('samples');

        for (const sample of FACTORY_SEED_SAMPLES) {
            store.put(sample);
        }

        return new Promise((resolve) => {
            tx.oncomplete = () => {
                console.log(`[SeedDataset] ${FACTORY_SEED_SAMPLES.length} muestras de calibración cargadas en Banco IA.`);
                resolve(FACTORY_SEED_SAMPLES.length);
            };
            tx.onerror = () => resolve(0);
        });
    } catch (err) {
        console.error('[SeedDataset] Error cargando muestras semilla:', err);
        return 0;
    }
}

if (typeof window !== 'undefined') {
    window.loadFactorySeedSamplesToDB = loadFactorySeedSamplesToDB;
    window.FACTORY_SEED_SAMPLES = FACTORY_SEED_SAMPLES;
}
